CREATE TABLE `dim_date` (`date_key` INTEGER NOT NULL,`full_date` DATE NOT NULL,`day` INTEGER NOT NULL,`month` INTEGER NOT NULL,`quarter` INTEGER NOT NULL,`year` INTEGER NOT NULL,PRIMARY KEY (`date_key`),UNIQUE INDEX `dim_date_full_date_key`(`full_date`),INDEX `dim_date_year_month_idx`(`year`,`month`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `dim_product` (`product_key` INTEGER NOT NULL AUTO_INCREMENT,`product_id` VARCHAR(50) NOT NULL,`product_name` VARCHAR(160) NOT NULL,`category` VARCHAR(80) NOT NULL,`brand` VARCHAR(80) NULL,PRIMARY KEY (`product_key`),UNIQUE INDEX `dim_product_product_id_key`(`product_id`),INDEX `dim_product_category_idx`(`category`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `dim_customer` (`customer_key` INTEGER NOT NULL AUTO_INCREMENT,`customer_id` VARCHAR(50) NOT NULL,`customer_name` VARCHAR(160) NOT NULL,`province` VARCHAR(100) NULL,`region` VARCHAR(80) NULL,PRIMARY KEY (`customer_key`),UNIQUE INDEX `dim_customer_customer_id_key`(`customer_id`),INDEX `dim_customer_region_idx`(`region`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `dim_store` (`store_key` INTEGER NOT NULL AUTO_INCREMENT,`store_id` VARCHAR(50) NOT NULL,`store_name` VARCHAR(160) NOT NULL,`province` VARCHAR(100) NULL,PRIMARY KEY (`store_key`),UNIQUE INDEX `dim_store_store_id_key`(`store_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `fact_sales` (`sales_key` BIGINT NOT NULL AUTO_INCREMENT,`order_id` VARCHAR(50) NOT NULL,`order_item_id` VARCHAR(50) NOT NULL,`date_key` INTEGER NOT NULL,`product_key` INTEGER NOT NULL,`customer_key` INTEGER NOT NULL,`store_key` INTEGER NOT NULL,`quantity` INTEGER NOT NULL,`unit_price` DECIMAL(14,2) NOT NULL,`discount_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,`total_amount` DECIMAL(14,2) NOT NULL,PRIMARY KEY (`sales_key`),UNIQUE INDEX `fact_sales_order_id_order_item_id_key`(`order_id`,`order_item_id`),INDEX `fact_sales_date_key_idx`(`date_key`),INDEX `fact_sales_product_key_idx`(`product_key`),INDEX `fact_sales_customer_key_idx`(`customer_key`),INDEX `fact_sales_store_key_idx`(`store_key`),CONSTRAINT `fact_sales_date_key_fkey` FOREIGN KEY (`date_key`) REFERENCES `dim_date`(`date_key`),CONSTRAINT `fact_sales_product_key_fkey` FOREIGN KEY (`product_key`) REFERENCES `dim_product`(`product_key`),CONSTRAINT `fact_sales_customer_key_fkey` FOREIGN KEY (`customer_key`) REFERENCES `dim_customer`(`customer_key`),CONSTRAINT `fact_sales_store_key_fkey` FOREIGN KEY (`store_key`) REFERENCES `dim_store`(`store_key`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
